package com.eventos.api.service;
import com.eventos.api.dto.AuthDtos.*; import com.eventos.api.entity.Admin; import com.eventos.api.repository.AdminRepository; import com.eventos.api.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class AuthService { private final AdminRepository admins; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(AdminRepository admins,PasswordEncoder encoder,JwtService jwt){this.admins=admins;this.encoder=encoder;this.jwt=jwt;} public void register(Register body){if(admins.findByEmail(body.email.toLowerCase()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Este email já está cadastrado."); Admin a=new Admin();a.setName(body.name);a.setEmail(body.email);a.setPasswordHash(encoder.encode(body.password));admins.save(a);} public Token login(Login body){Admin a=admins.findByEmail(body.email.toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email ou senha inválidos."));if(!encoder.matches(body.password,a.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email ou senha inválidos.");return new Token(jwt.create(a.getId(),a.getEmail()),a.getName());} }
